bool mrhiFeaturesWithin(const mrhiFeatures* asked, const mrhiFeatures* granted)
{
    return true
        && (!asked->timestampQuery || granted->timestampQuery)
        && (!asked->pipelineStatisticsQuery || granted->pipelineStatisticsQuery)
        && (!asked->textureCompressionBc || granted->textureCompressionBc)
        && (!asked->textureCompressionEtc2 || granted->textureCompressionEtc2)
        && (!asked->textureCompressionAstc || granted->textureCompressionAstc)
        && (!asked->float32Filterable || granted->float32Filterable)
        && (!asked->rg11b10Renderable || granted->rg11b10Renderable)
        && (!asked->dualSourceBlending || granted->dualSourceBlending)
        && (!asked->unclippedDepth || granted->unclippedDepth)
        && (!asked->shaderF16 || granted->shaderF16)
        && (!asked->subgroups || granted->subgroups)
        && (!asked->shaderInt64 || granted->shaderInt64)
        && (!asked->indirectFirstInstance || granted->indirectFirstInstance)
        && (!asked->multiDrawIndirectCount || granted->multiDrawIndirectCount)
        && (!asked->multiview || granted->multiview)
        && (!asked->bindlessSampling || granted->bindlessSampling)
        && (!asked->bindlessHeterogeneous || granted->bindlessHeterogeneous)
        && (!asked->presentTiming || granted->presentTiming);
}

